    uint8_t t = (a + b + x) & 0xFF;
    return ((t << 2) | (t >> 6)) & 0xFF;
}
uint32_t f_function(uint32_t v) {
    uint8_t x[4], y[4];
    for (int i=0;i<4;i++){ x[i]=v&0xFF; v>>=8; }
    y[2]=g_function(x[3]^x[2], x[1]^x[0], 1);
    y[3]=g_function(x[3], y[2], 0);
    y[1]=g_function(x[1]^x[0], y[2], 0);
    y[0]=g_function(x[0], y[1], 1);
    uint32_t o=0;
    for (int i=0;i<4;i++) o |= (uint32_t)y[i]<<(8*i);
    return o;
}
uint32_t expand(uint32_t k){ return k ^ (k<<16) ^ (k*12345); }
int main(){
    long long a[32], b[32];
    FILE *f=fopen("/app/pairs.txt","r");
    int n=0;
    while(n<32 && fscanf(f, "%lld %lld", &a[n], &b[n])==2) n++;
    fclose(f);
    uint32_t L[32], R[32];
    for(int i=0;i<n;i++){ L[i]=(uint32_t)(b[i]>>32); R[i]=(uint32_t)((uint32_t)(b[i]>>32)^(uint32_t)b[i]); }
    for(int r=3; r>=0; r--){
        int found=0;
        for(uint32_t s=0; s<(1u<<20); s++){
            uint32_t K=expand(s&0xFFFFF);
            int ok=1;
            for(int i=0;i<n;i++) if(L[i] != R[i]^f_function(R[i]^K)) { ok=0; break; }
            if(ok){ printf("seed[%d]=0x%05X\n", r, s); found=1; break; }
        }
        if(!found){ printf("failed at round %d\n", r); return 1; }
        for(int i=0;i<n;i++){ uint32_t nR=L[i]; uint32_t nL=R[i]^f_function(nR^K); L[i]=nL; R[i]=nR; }
    }
    return 0;
}
